const fs = require("node:fs/promises");
const path = require("node:path");
const { randomUUID } = require("node:crypto");
const pool = require("../db");
const config = require("../config");

const STORAGE_DIR = config.UPLOAD_DIR;

/**
 * Storage keys are generated by this service and are always UUIDs. Validating
 * them before they are used to build a file path makes path traversal
 * impossible even if a key was tampered with in the database.
 */
const STORAGE_KEY_PATTERN =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function isValidStorageKey(storageKey) {
    return typeof storageKey === "string" && STORAGE_KEY_PATTERN.test(storageKey);
}

function storagePath(storageKey) {
    if (!isValidStorageKey(storageKey)) {
        throw new Error("Invalid storage key");
    }
    return path.join(STORAGE_DIR, storageKey);
}

async function ensureStorageDirectory() {
    await fs.mkdir(STORAGE_DIR, { recursive: true });
}

async function saveTemporaryFile(buffer, db = pool) {
    if (!Buffer.isBuffer(buffer) || buffer.length === 0) {
        throw new Error("Cannot store an empty file");
    }

    await ensureStorageDirectory();
    const storageKey = randomUUID();
    const filePath = storagePath(storageKey);
    await fs.writeFile(filePath, buffer, { flag: "wx", mode: 0o600 });

    try {
        await db.query(
            `INSERT INTO document_blobs (storage_key, file_data)
             VALUES ($1, $2)
             ON CONFLICT (storage_key) DO UPDATE SET file_data = EXCLUDED.file_data`,
            [storageKey, buffer]
        );
    } catch (err) {
        // If the DB insert fails after the file was already written to disk,
        // delete the orphaned file so disk and DB never drift apart.
        await fs.unlink(filePath).catch(() => {});
        throw err;
    }

    return { storageKey, filePath, size: buffer.length };
}

/**
 * Reads a stored document.
 * The database blob is the source of truth; the file system copy is only a
 * write-through cache that is used when the blob row is unavailable.
 */
async function getFileBuffer(storageKey) {
    const dbResult = await pool.query(
        "SELECT file_data FROM document_blobs WHERE storage_key = $1 LIMIT 1",
        [storageKey]
    );

    if (dbResult.rows.length > 0 && dbResult.rows[0].file_data) {
        return dbResult.rows[0].file_data;
    }

    return await fs.readFile(storagePath(storageKey));
}

async function deleteFile(storageKey, db = pool) {
    // The database row is removed unconditionally: the storage key is a
    // primary key, no file system path is built from it.
    await db.query("DELETE FROM document_blobs WHERE storage_key = $1", [storageKey]).catch(() => {});

    // The file system is only touched for a valid key. An invalid key was
    // tampered with and could point outside the upload directory.
    if (!isValidStorageKey(storageKey)) {
        return;
    }

    await fs.unlink(storagePath(storageKey)).catch(() => {});
}

module.exports = {
    ensureStorageDirectory,
    saveTemporaryFile,
    getFileBuffer,
    deleteFile,
    isValidStorageKey,
    STORAGE_DIR
};
